-- 0008 · DLP de convivencia: lenguaje ofensivo y contenido sexual en foros, salas y perfiles.
-- No borra ni modifica datos existentes: agrega dos categorías al catálogo y sus reglas, que se
-- activan o desactivan desde el panel como las demás (F31). Las mismas reglas están en
-- db/seed/reglas_dlp.json (el seed las recarga); test/dlp-lenguaje.test.ts comprueba que los
-- patrones de los dos archivos sean idénticos.
--
-- Los patrones se evalúan sobre el texto normalizado (minúsculas, sin tildes, sin homoglifos ni
-- caracteres invisibles) y, por ser de categorías de lenguaje, también sobre variantes con
-- leetspeak, signos intercalados, letras repetidas, comodines y fragmentos separados
-- (dlp.analizador.ts → variantesLenguaje). Por eso las letras dobles se escriben opcionales
-- («perr?a»): «perrrra» se compara también como «pera».

insert into app.categoria_dlp (codigo, nombre, descripcion, orden) values
  ('lenguaje_ofensivo', 'Lenguaje ofensivo',
   'Groserías, insultos dirigidos, acoso y expresiones discriminatorias.', 7),
  ('contenido_sexual', 'Contenido sexual',
   'Lenguaje sexual vulgar, doble sentido sexual y solicitudes de fotos o contenido íntimo.', 8)
on conflict (codigo) do nothing;

insert into app.regla_dlp (codigo, categoria, descripcion, patron) values
  ('ofensivo-hijueputa', 'lenguaje_ofensivo',
   '«Hijo de puta» y sus variantes colombianas (hijueputa, jueputa, ijueputa, hijo e puta…), también con letras omitidas o pegadas.',
   '\b(?:h?ij(?:o|ue|o\s?e|u)\s?(?:de\s?)?(?:la\s?)?(?:gran\s?)?|h?ue\s?|j[uv]e\s?)p[uv]t[ao]s?\b'),
  ('ofensivo-groserias', 'lenguaje_ofensivo',
   'Groserías explícitas: puta y derivados, mierda, verga, culo, joder, carajo, coño, cabrón, pendejo, malparido, pirobo.',
   '\bp[uv]t(?:a|o|as|os|ada|adas|ear|ea|eando|isima|isimo|ero|eria|amadre|o\s?madre)\b|\bptas?\b|\bm(?:i?e?)rd(?:a|as|ita|itas|oso|osa|osos|osas)\b|\b[bv]err?g(?:a|as|azo|ota|on|uer[oa]s?)\b|\bvrga?s?\b|\b[ck][uv]l(?:o|os|ito|azo|on|ona|ones|onas|ote)\b|\bno\s+(?:me|nos|lo|la|te)\s+jod(?:as|a|an|e|es|is)\b|\bjod(?:ete|anse|ase|er)\b|\ba\s+joderse\b|\bque\s+se\s+jod(?:a|an)\b|\bgilipollas\b|\bcarajo\b|\bque\s+cono\b|\bcojones\b|\bconch(?:a\s?(?:de\s?)?(?:tu|su)\s?madre|etumadre|etumare|esumadre|esumare)\b|\bme\s+cago\s+en\b|\b[ck][a]?[bv]r[o]?n(?:a|es|as|azo)?\b|\bp[e]?nd[e]?j(?:o|a|os|as|ada|adas)\b|\bmal\s?pa?ri?d[oa]s?\b|\bpir[o]?b[oa]s?\b'),
  ('ofensivo-coloquial', 'lenguaje_ofensivo',
   'Insultos coloquiales colombianos: gonorrea (salvo en contexto de salud), care-, mamagüevo, güevón, marica, monda, «me vale huevo».',
   '^(?!.*\b(?:infeccion\w*|its|ets|transmision|sexual\w*|sintomas?|medic\w*|salud|contagi\w*|prevenir|previene|prevencion|condon\w*|preservativ\w*|enfermedad\w*|tratamiento|bacteria\w*|antibiotic\w*|vih|clamidia|sifilis)\b).*\bg[o]?n[o]?rr?[e]?[ai]a?s?\b|\b[ck]ar[ae]\s?(?:de\s?|e\s?)?(?:chimba|[bv]err?ga|monda|picha|culo|mierda|pinga|g[uw]?e[bv]o|h[uw]?e[bv]o|nalga|pene|pito|chucha)s?\b|\bmama\s?(?:g|w)u?e[bv]os?\b|\bmamah?ue[bv]os?\b|\bchupa\s?(?:h|g|w)?u?e[bv]os?\b|\bmama\s?(?:[bv]err?ga|pinga|monda|picha)s?\b|\b(?:h|g)?u?e[bv]on(?:a|as|es|azo|ada|adas)?\b|\bwe[bv]?on(?:a|as|es|azo|ada|adas)?\b|\bgvn\b|\bmaric(?:a|as|o|os|on|ona|ones|onas|ada|adas|onada|onadas)\b|\bmks?\b|\b(?:vale|valio|chupa|chupe|que|la|mi|tu|su)\s+monda\b(?!\s+de\s+(?:naranja|papa|mandarina|fruta)\b)|\bme\s+(?:vale|valio|importa)\s+(?:un\s+)?(?:h|g|w)?u?e[bv]o\b|\b(?:rasc|chup|lam|sob)\w*\s+(?:los|mis|tus|sus|las|el|tu|mi)\s+(?:(?:h|g|w)?u?e[bv]os|webos)\b|\b(?:rasc|chup|lam|sob)\w*\s+(?:las|mis|tus|sus)\s+(?:bolas|pelotas)\b'),
  ('ofensivo-abreviaturas', 'lenguaje_ofensivo',
   'Abreviaturas de groserías (hpta, jpta, hdp, ptm, ctm, mmgv…) y «hp» como insulto, salvo en contexto de computadores o juegos.',
   '\b(?:hpt[ao]?s?|hjpt[ao]?|jpt[ao]s?|hdpm?|ptm|ctm|csm|mmg[bv]?o?|mmgv|hmp)\b|(?<!\d\s?)\blpm\b|^(?!.*\b(?:impresora|impresoras|computador|computadora|portatil|laptop|pc|tinta|cartucho|marca|juego|videojuego|vida|puntos|caballos|motor|pantalla|teclado)\b)(?:.*\b(?:ese|esa|esos|esas|eres|sos|so|que|man|vieja|viejo|bobo|boba|sapo|sapa|perro|perra|malparid[oa]|gonorrea|maldit[oa]|marica|gran|pirob[oa]|ladron|ladrona|gamin)\s+hps?\b|\s*hps?\b(?!\s*\d)|.*\bhps?\s*[!¡]|.*\bhps?\s+(?:malparid|gonorrea|de\s+mierda|perr|hijueput|sapo|bobo|marica))'),
  ('ofensivo-insulto-dirigido', 'lenguaje_ofensivo',
   'Insultos dirigidos a una persona («eres un idiota», «cállate, imbécil», «esa estúpida», «eres una perra»). No bloquea la palabra suelta: «me sentí como un idiota» se permite.',
   '\b(?:eres|sos|seras|es\s+usted|usted\s+es|ustedes\s+son|pedazo\s+de|maldit[oa]s?|callate|callese|callense|cierra\s+(?:la\s+)?(?:boca|jeta|trompa)|so)[\s,]*(?:(?:un|una|unos|unas|el|la|re|muy|tan|mas|bien|gran|grandisim[oa]|tremend[oa]|pinche|reverend[oa])[\s,]*){0,2}(?:idiotas?|pelotud[oa]s?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?|inutil(?:es)?|cagon(?:a|es|as)?|basuras?|escorias?|asco|asqueros[oa]s?|porquerias?|lacras?|fracasad[oa]s?|perdedor(?:a|es|as)?|fe[oa]s?|gord[oa]s?|perr?as?|zorr?as?|cerd[oa]s?|marr?an[oa]s?|vacas?|ballenas?|ratas?|sap[oa]s?|cucarachas?|mic[oa]s?|simios?|changos?|gorilas?)\b|\bhij[oa]s?\s+de\s+(?:perr?a|zorr?a)s?\b|\b(?:es|son)\s+(?:un|una|unos|unas)\s+(?:(?:re|muy|gran|tremend[oa]|reverend[oa]|pinche)\s+)?(?:idiotas?|pelotud[oa]s?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?)\b|\b(?:ese|esa|esos|esas|este|esta|estos|estas|vieja|viejo|man|parce)\s+(?:(?:man|vieja|viejo|tipo|tipa|pelad[oa]|profe|chino|china)\s+)?(?:idiotas?|pelotud[oa]s?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?)\b(?!\s+(?:de|que|para|en)\b)|\bque\s+(?:idiotas?|pelotud[oa]s?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?|inutil(?:es)?|cagon(?:a|es|as)?|basuras?|escorias?|asco|asqueros[oa]s?|porquerias?|lacras?|fracasad[oa]s?|perdedor(?:a|es|as)?|fe[oa]s?|gord[oa]s?|perr?as?|zorr?as?|cerd[oa]s?|marr?an[oa]s?|vacas?|ballenas?|ratas?|sap[oa]s?|cucarachas?|mic[oa]s?|simios?|changos?|gorilas?)\s+(?:eres|sos|es|son)\b|^(?:idiotas?|pelotud[oa]s?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?)\s*[,!¡]|[,!¡]\s*(?:idiotas?|pelotud[oa]s?|estupid[oa]s?|imbecil(?:es)?|tarad[oa]s?|retrasad[oa]s?|subnormal(?:es)?|mongolic[oa]s?|mogolic[oa]s?|malnacid[oa]s?|desgraciad[oa]s?|cretin[oa]s?|anormal(?:es)?)\s*[.!¡?]*$'),
  ('ofensivo-acoso', 'lenguaje_ofensivo',
   'Deseos de muerte, incitación a hacerse daño e insultos discriminatorios (veneco, sudaca, machorra…). No bloquea «me quiero morir»: eso es una señal de ayuda.',
   '\bojala\s+(?:te\s+mueras|se\s+muera|se\s+mueran|te\s+maten|te\s+murieras|no\s+existieras|te\s+pase\s+algo)\b|\b(?:matate|suicidate|ahorcate|pegate\s+un\s+tiro|tirate\s+(?:de|por)\s+(?:un|el|la)\s+(?:puente|ventana|edificio|balcon))\b|\bmuerete\b(?!\s+de\s+(?:la\s+)?(?:risa|envidia))|\b(?:venec[oa]s?|sudacas?|machorras?|travelos?|sidos[oa]s?)\b'),
  ('sexual-explicito', 'contenido_sexual',
   'Lenguaje sexual vulgar: culiar, follar, pajearse, jalársela, pinga, tetas, porno, nudes, «el pack», sexo por cámara o «contigo».',
   '\b[ck][uv]l(?:i|e)(?:ar|arte|arla|arlo|arme|arnos|ando|ado|ada|ados|adas|ao|amos|emos|en|o|a)\b|\bfoll?(?:ar|arte|arla|arlo|ame|amos|ando|o|e|en|aria)\b|\bpajea(?:r|rse|rte|rme|ndo|ndome|ndose)\b|\bpajeo\b|\bhacer(?:se|te|me|nos)\s+(?:una\s+|la\s+)?paja\b|\bme\s+hago\s+(?:una\s+|la\s+)?paja\b|\b(?:me|te|se)\s+la\s+(?:jalo|jalas|jala|jale|halo|halas|sacudo)\b|\bjalar(?:se|te|me)la\b|\b(?:masturb\w+|me\s+toco|me\s+vengo|me\s+mojo)\s+(?:pensando\s+en\s+ti|viendote|contigo|con\s+tus?\s+fotos?)\b|\bpingas?\b|\bpichas?\b|\btet(?:as|otas|ona|onas|ota)\b|\bcachond[oa]s?\b|\bporno(?:s)?\b|\bxxx\b|\bnudes\b|\b(?:un|una|tus|tu|el|tienes)\s+nude\b|\bsexting\b|\b(?:pasa|pasame|manda|mandame|envia|enviame|vende|vendo|tienes|tenes|quiero|regalame|muestrame|comparte|compartime)\s+(?:(?:el|tu|un|ese|algun|su|tus)\s+)?packs?\b(?!\s+de\b)|\bsexo\s+(?:oral|anal|por\s+(?:camara|video|videollamada|chat)|virtual\s+conmigo|virtual\s+contigo)\b|\b(?:hagamos|tengamos|hacemos|tenemos)\s+(?:el\s+)?sexo\b|\bhagamoslo\b|\bsexo\s+(?:\w+\s+)?(?:contigo|conmigo)\b|\b(?:hacerlo|acostarme|acostarnos|culiar|tirar)\s+contigo\b|\bhagamos\s+el\s+amor\b'),
  ('sexual-imagenes', 'contenido_sexual',
   'Pedir o mostrar fotos íntimas o partes del cuerpo («mándame fotos desnuda», «desnúdate», «quieres ver mi pito»), salvo en contexto médico.',
   '\b(?:mandame|pasame|enviame|manda|pasa|envia|muestrame|ensename|quiero\s+ver|tienes|tenes|sube|subeme)\s+(?:(?:una|unas|un|el|tu|tus|algun|alguna|algunas)\s+)?(?:fotos?|videos?|fotitos?)\s+(?:(?:tuy[oa]s?|de\s+ti)\s+)?(?:desnud[oa]s?|sin\s+ropa|en\s+ropa\s+interior|en\s+(?:tanga|calzones?|brasier|bra|interiores)|intim[oa]s?|hot|calientes?|xxx|sexys?|sensuales?)\b|\b(?:verte|mirarte|tenerte)\s+(?:desnud[oa]|sin\s+ropa|en\s+ropa\s+interior|en\s+tanga)\b|\b(?:desnudate|empelotate|encuerate)\b|\bquitate\s+(?:toda\s+)?la\s+ropa\s+(?:para\s+mi|por\s+camara|en\s+la\s+camara)\b|^(?!.*\b(?:medic\w*|doctor\w*|enfermer\w*|salud|consulta|ginecolog\w*|urolog\w*|duele|dolor|revision|examen|cita)\b).*\b(?:ver|veas|mirar|mires|toca|tocar|tocame|tocarte|tocarme|agarra|agarrame|mostrar|mostrarte|muestrame|ensenar|ensenarte|ensename)\s+(?:mi|tu|su|mis|tus|sus)\s+(?:pito|pene|pipi|[bv]err?ga|pinga|cuca|vagina|chocho|culo|nalgas|tetas|senos|pechos|partes\s+intimas|cosita)\b'),
  ('sexual-actos', 'contenido_sexual',
   'Actos sexuales en imperativo o dirigidos («chúpamela», «mámamela», «chupa el pico», «mama la verga»).',
   '\b(?:chupa|mama|lame)(?:mel[ao]s?|l[ao]|n?mela)\b|\b(?:me|te|se)\s+la\s+(?:chupas|chupa|chupo|chupe|chupan|mamas|mamo|mame|maman)\b|\b(?:chup|lam)(?:a|ame|ar|arte|enme|ate|o|e|en|amela)\s+(?:(?:el|la|los|las|mi|mis|tu|tus|este|esta|un|una)\s+)?(?:[bv]err?gas?|pingas?|poll?as?|pico|pito|pene|h?[gw]?ue[bv]os?|bolas|cuca|chocho|culo|monda|picha|chimba|tetas?|nalgas?|vagina)\b(?!\s+(?:de|y)\b)|\bmam(?:ame|ar|arte|enme|ate|o|en|amela)\s+(?:(?:el|la|los|las|mi|mis|tu|tus|este|esta|un|una)\s+)?(?:[bv]err?gas?|pingas?|poll?as?|pico|pito|pene|h?[gw]?ue[bv]os?|bolas|cuca|chocho|culo|monda|picha|chimba|tetas?|nalgas?|vagina)\b(?!\s+(?:de|y)\b)|\bmama\s+(?:(?:el|la|mi|tu|este|esta)\s+)?(?:[bv]err?gas?|pingas?|monda|picha|chimba|g[uw]?e[bv]os?|webos?)\b|\bpico\s+(?:pa|pal|para|para\s+el)\s+(?:el\s+)?que\s+(?:lo\s+)?(?:lea|lee)\b'),
  ('sexual-doble-sentido', 'contenido_sexual',
   'Doble sentido con intención sexual en contexto («te la quiero meter», «te doy por detrás», «se me paró pensando en ti», «te voy a comer toda», «ponte en cuatro»). Las palabras sueltas (pico, leche, comer, duro) no se bloquean.',
   '\bte\s+la\s+(?:(?:quiero|voy\s+a|vamos\s+a|puedo|quisiera)\s+)?(?:meter|meto|meteria|metiera|clavo|clavar|clavaria|chupo|chupar|mamo|mamar|ensarto|ensartar|hundo|entierro|empujo)\b|\bte\s+(?:la\s+)?(?:doy|dare|voy\s+a\s+dar|quiero\s+dar|daria|daba)\s+(?:(?:bien|muy|tan)\s+)?(?:por\s+(?:detras|atras|el\s+culo|la\s+cola)|leche|lechita|[bv]err?ga|pico|pinga|duro(?=\s+(?:toda\s+la\s+noche|en\s+la\s+cama|contra|y\s+rico|rico|mami|mamita|mamacita|bebe|nena|hasta)))\b|\b(?:probar|tomar|tomate|tragar|tragate|quieres|queres)\s+(?:mi|toda\s+mi|mi\s+rica)\s+(?:leche|lechita)\b|\b(?:mi|tu)\s+lechita\b|\bse\s+me\s+(?:paro|para|pone|puso|levanto|levanta)\s+(?:(?:la|el)\s+(?:[bv]err?ga|pinga|pito|pene|monda|picha|amigo|soldado)\s+)?(?:(?:dur[ao]|parad[ao])\s+)?(?:pensando\s+en\s+ti|contigo|al\s+verte|viendote|de\s+verte|por\s+ti)\b|\b(?:la|lo)\s+tengo\s+(?:bien\s+|muy\s+)?(?:dur[ao]|parad[ao])\s+(?:por\s+ti|pensando|contigo|para\s+ti)\b|\b(?:algo|una\s+cosa)\s+(?:bien\s+|muy\s+)?(?:dur[ao]|grande|parad[ao])\s+(?:para\s+ti|pa\s+ti|pati)\b|\bte\s+(?:(?:voy|vamos)\s+a\s+|quiero\s+)?(?:comer|comeria|comiera|como)\s+(?:toda|todo|enterit[ao]|enter[oa]|vivit[ao]|despacito|completit[ao])\b|\b(?:ponte|ponerte|pongase|te\s+pongo|te\s+quiero\s+poner|ponla|ponerla|pongamos)\s+(?:en\s+)?cuatro\b|^(?!.*\b(?:ejercicio\w*|estiramiento\w*|estirar|yoga|gimnasia|entrenamiento|calentamiento|educacion\s+fisica|baile|danza|parto)\b).*\b(?:abre|abrete|abreme|abrir|abras)\s+(?:las|tus)\s+(?:piernas|nalgas|patas)\b'),
  ('sexual-acoso', 'contenido_sexual',
   'Comentarios sexuales dirigidos a una persona («estás muy rica», «mamacita rica», «te quiero coger»).',
   '\bestas\s+(?:muy\s+|bien\s+|re\s+|tan\s+|bastante\s+)?(?:rica|rico|buenota|buenote|buenisima|sabrosa|sabroso|apetitosa|apetitoso|mamacita|mamasita|(?:buena|buenisima)(?!\s+(?:para|en|haciendo|con|jugando|onda|gente)\b))\b|\b(?:mamacita|mamasita|mamita|papacito|papasito|bizcocho|nena|mami|papi)\s+(?:tan\s+|muy\s+|bien\s+)?(?:rica|rico|sabrosa|sabroso|buenota|buenote|deliciosa|delicioso|cachonda|cachondo)\b|\b(?:co[gj]erte|te\s+quiero\s+co[gj]er(?!\s+(?:la|el|de|para)\b)|co[gj]erla\s+toda)\b')
on conflict (codigo) do nothing;
